create table if not exists public.mini_messages (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, content text not null check (char_length(trim(content)) between 1 and 500), created_at timestamptz not null default now()); alter table public.mini_messages enable row level security; drop policy if exists "Mini messages: read own" on public.mini_messages; create policy "Mini messages: read own" on public.mini_messages for select to authenticated using (auth.uid() = user_id); drop policy if exists "Mini messages: insert own" on public.mini_messages; create policy "Mini messages: insert own" on public.mini_messages for insert to authenticated with check (auth.uid() = user_id); drop policy if exists "Mini messages: delete own" on public.mini_messages; create policy "Mini messages: delete own" on public.mini_messages for delete to authenticated using (auth.uid() = user_id); grant select, insert, delete on public.mini_messages to authenticated; grant usage, select on sequence public.mini_messages_id_seq to authenticated;